   "<b>你這場顧 2 個組別：國中進階、國小進階</b>（上午接續排滿，一張地圖可能坐兩組）；兩組的題目都要讀，題目袋也要拿兩份，判每一隊前先看他是哪一組",
   "08:15–08:50 檢查地圖 M21、M22：地圖蓋著（背面朝上）、道具數量、桌牌隊伍編號（下午：桌牌旋轉翻到下午那一面，地圖不用換）；備用道具（易開罐、乒乓球、計分表、筆）在你的椅子下，比賽中缺了自己補；證書袋在你的位置上",
