   "約 16:10 循線比完就拍：帶得獎隊伍到分區頒獎背景 6 拍一組一張大合照（L1＝國中循線前五名、優勝、佳作；L2＝高中循線第一、二名）；攝影師拍，拍不到就用手機拍、照片上傳大會雲端",
   "16:30–17:00 頒獎時段先做：L1 把國中循線（JL）前五名帶到主舞台頒獎排隊區交給大會頒獎人員；L2 把高中循線（HL）第一、二名帶到主舞台頒獎排隊區交給大會頒獎人員（聯盟名次獎狀＋獎盃＋每位隊員獎牌，上主舞台）；回來再發參賽證明",
   "16:30–17:00 頒獎時段：向大會計分台領相撲／循線參賽證明（依組別→隊伍），在循線區照組別、隊伍編號發給各隊（2 位分工：L1 國中、L2 高中），發完再交接",
   "16:30–17:00 交接：計分表、道具交給主辦核心人員，歸還工作證，17:00 簽退；願意留下的志工協助頒獎尾段與撤場到 18:30（主辦核心（組長 G1、G2、大會計分台（協會人員））負責）"
